import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { validateMetricRegistry } from "../src/metric-registry.ts";

const here = dirname(fileURLToPath(import.meta.url));
const registryPath = resolve(here, "../../../specs/metrics.v0.json");

const frozen = (): Record<string, unknown> =>
  JSON.parse(readFileSync(registryPath, "utf8"));

const normalized = (value: string): string =>
  value.toLowerCase().replace(/[^a-z0-9]/g, "");

const diagnoses = (
  result: ReturnType<typeof validateMetricRegistry>,
  field: string
): boolean =>
  result.errors.some((message) =>
    normalized(message).includes(normalized(field))
  );

const mustRejectAtRoot = (
  label: string,
  registry: Record<string, unknown>,
  field: string
): void => {
  const result = validateMetricRegistry(registry);
  assert.equal(result.ok, false, `${label} was accepted`);
  assert.ok(
    diagnoses(result, field),
    `${label} was not diagnosed as a ${field} root-contract violation: ${result.errors.join("; ")}`
  );
};

test("registry-level-contract-fields", () => {
  assert.equal(
    validateMetricRegistry(frozen()).ok,
    true,
    "the shipped contract-v1 registry must remain valid"
  );

  const rootFields = [
    "registry_id",
    "contract_version",
    "source_contract",
    "consumers",
    "route_tables",
    "frontiers",
    "metrics"
  ];

  const wrongTypes: Record<string, unknown> = {
    registry_id: null,
    contract_version: null,
    source_contract: null,
    consumers: {},
    route_tables: [],
    frontiers: [],
    metrics: {}
  };

  for (const field of rootFields) {
    const missing = frozen();
    delete missing[field];
    mustRejectAtRoot(`registry without ${field}`, missing, field);

    const malformed = frozen();
    malformed[field] = wrongTypes[field];
    mustRejectAtRoot(`registry with malformed ${field}`, malformed, field);
  }

  const wrongRegistryId = frozen();
  wrongRegistryId.registry_id = "metrics.v1";
  mustRejectAtRoot("registry with a changed registry_id", wrongRegistryId, "registry_id");

  const wrongSourceContract = frozen();
  wrongSourceContract.source_contract = "docs/contracts/metric-scoring-contract-v2.md";
  mustRejectAtRoot(
    "registry with a changed source_contract",
    wrongSourceContract,
    "source_contract"
  );
});
